'use client'

import * as React from 'react'
import { cn } from '@/lib/utils'
import { attachGpuGate, deferUntilVisible } from '@/lib/gpu-runtime'
import { logger } from '@/utils/logger'
import { SILK_FLARE_WGSL } from './silk-flare.wgsl'

export type SilkFlareFrom = 'bottom' | 'top'

export type SilkFlareProps = {
  color1: string
  color1Opacity?: number
  color2: string
  color2Opacity?: number
  color3: string
  color3Opacity?: number
  heatBaseColor?: string
  heatBaseColorOpacity?: number
  hotColor?: string
  heatOpacity?: number
  from?: SilkFlareFrom
  speed?: number
  animate?: boolean
  grain?: boolean
  dpr?: number
  fps?: number
  rootMargin?: string
  className?: string
}

function hexToRgba(hex: string, alpha = 1): [number, number, number, number] {
  const h = hex.replace('#', '')
  const a = h.length >= 8 ? parseInt(h.slice(6, 8), 16) / 255 : alpha
  return [parseInt(h.slice(0, 2), 16) / 255, parseInt(h.slice(2, 4), 16) / 255, parseInt(h.slice(4, 6), 16) / 255, a]
}

function shaderParams(cur: {
  color1: string
  color1Opacity?: number
  color2: string
  color2Opacity?: number
  color3: string
  color3Opacity?: number
  heatBaseColor?: string
  heatBaseColorOpacity?: number
  hotColor?: string
  heatOpacity?: number
  from?: SilkFlareFrom
  speed: number
  grain: boolean
}) {
  return {
    timeSpeed: cur.speed * 0.25,
    color1: hexToRgba(cur.color1, cur.color1Opacity ?? 0.3),
    color2: hexToRgba(cur.color2, cur.color2Opacity ?? 0.3),
    color3: hexToRgba(cur.color3, cur.color3Opacity ?? 0.3),
    heatBaseColor: hexToRgba(cur.heatBaseColor ?? '#2a7bba', cur.heatBaseColorOpacity ?? 0.5),
    hotColor: hexToRgba(cur.hotColor || cur.color3),
    warp: [1, 5, 2, 50],
    blend: [0, 0.05, 0, 500],
    grain: [cur.grain ? 0.1 : 0, 2, 0, 2],
    look: [1.5, 1, 1, 0.9],
    center: [0, 0],
    fromTop: cur.from === 'top' ? 1 : 0,
    heatOpacity: cur.heatOpacity ?? 0.5,
  }
}

export function SilkFlare({
  color1,
  color1Opacity = 0.3,
  color2,
  color2Opacity = 0.3,
  color3,
  color3Opacity = 0.3,
  heatBaseColor = '#2a7bba',
  heatBaseColorOpacity = 0.5,
  hotColor,
  heatOpacity = 0.5,
  from = 'bottom',
  speed = 0.8,
  animate = true,
  grain = true,
  dpr,
  fps,
  rootMargin = '80px',
  className,
}: SilkFlareProps) {
  const canvasRef = React.useRef<HTMLCanvasElement>(null)
  const propsRef = React.useRef({
    color1,
    color1Opacity,
    color2,
    color2Opacity,
    color3,
    color3Opacity,
    heatBaseColor,
    heatBaseColorOpacity,
    hotColor,
    heatOpacity,
    from,
    speed,
    animate,
    grain,
  })
  propsRef.current = {
    color1,
    color1Opacity,
    color2,
    color2Opacity,
    color3,
    color3Opacity,
    heatBaseColor,
    heatBaseColorOpacity,
    hotColor,
    heatOpacity,
    from,
    speed,
    animate,
    grain,
  }

  React.useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    let cancelled = false
    let stopLoop: (() => void) | undefined
    let disposeGpu: (() => void) | undefined
    let disposeGate: (() => void) | undefined
    let disposeDefer: (() => void) | undefined

    async function mount() {
      const { init, effect, surface, clock, frameLoop } = await import('vgpu')
      if (cancelled || !canvasRef.current) return
      if (!('gpu' in navigator)) return
      const gpu = await init()
      if (cancelled) {
        gpu.dispose()
        return
      }

      let running: { stop: () => void } | undefined
      let draw = (_passFrame: { pass: (target: unknown, fx: unknown) => void }) => {}

      const gate = attachGpuGate(canvas, (paused) => {
        if (paused) {
          running?.stop()
          running = undefined
        } else if (!running) {
          running = frameLoop(gpu, (frame) => draw(frame))
        }
      })
      disposeGate = gate.dispose
      const pixelRatio = dpr ?? Math.min(window.devicePixelRatio || 1, 2)
      const frameMs = fps ? 1000 / fps : gate.frameMs
      const canvasSurface = surface(gpu, canvasRef.current, {
        dpr: pixelRatio,
        alphaMode: 'premultiplied',
        format: 'bgra8unorm',
      })
      const p = propsRef.current
      const shade = effect(gpu, SILK_FLARE_WGSL, {
        set: {
          params: {
            resolution: [1, 1],
            time: 0,
            ...shaderParams(p),
          },
        },
      })

      const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches
      let lastW = 0
      let lastH = 0
      let lastKey = ''
      let lastDraw = 0

      draw = (passFrame) => {
        if (gate.state.paused) return
        const now = performance.now()
        if (frameMs && now - lastDraw < frameMs) return
        lastDraw = now
        const width = Math.max(canvas.clientWidth, 1)
        const height = Math.max(canvas.clientHeight, 1)
        const cur = propsRef.current
        const moving = cur.animate && !reduced
        const next: Record<string, unknown> = {
          time: moving ? clock(gpu).time : 0,
        }
        const key = `${cur.color1}${cur.color1Opacity}${cur.color2}${cur.color2Opacity}${cur.color3}${cur.color3Opacity}${cur.heatBaseColor}${cur.heatBaseColorOpacity}${cur.hotColor}${cur.heatOpacity}${cur.from}${cur.speed}${cur.animate}${cur.grain}`
        if (key !== lastKey) {
          lastKey = key
          Object.assign(next, shaderParams(cur))
        }
        if (width !== lastW || height !== lastH) {
          lastW = width
          lastH = height
          next.resolution = [width, height]
        }
        shade.set({ params: next })
        passFrame.pass(canvasSurface, shade)
      }

      if (!gate.state.paused && !running) {
        running = frameLoop(gpu, (frame) => draw(frame))
      }
      stopLoop = () => {
        running?.stop()
        running = undefined
      }
      disposeGpu = () => gpu.dispose()
    }

    disposeDefer = deferUntilVisible(
      canvas,
      () => {
        mount().catch((error) => {
          logger.error('SilkFlare WebGPU init failed:', error)
        })
      },
      rootMargin,
    )

    return () => {
      cancelled = true
      disposeDefer?.()
      stopLoop?.()
      disposeGate?.()
      disposeGpu?.()
    }
  }, [dpr, fps, rootMargin])

  return <canvas ref={canvasRef} aria-hidden className={cn('block size-full', className)} />
}

export const SILK_FLARE_WGSL = /* wgsl */ `
struct Params {
  resolution: vec2f,
  time: f32,
  timeSpeed: f32,
  color1: vec4f,
  color2: vec4f,
  color3: vec4f,
  heatBaseColor: vec4f,
  hotColor: vec4f,
  warp: vec4f,
  blend: vec4f,
  grain: vec4f,
  look: vec4f,
  center: vec2f,
  fromTop: f32,
  heatOpacity: f32,
}

@group(0) @binding(0) var<uniform> params: Params;

fn rot(a: f32) -> mat2x2<f32> {
  let s = sin(a);
  let c = cos(a);
  return mat2x2<f32>(c, -s, s, c);
}

fn hash2(p: vec2f) -> vec2f {
  let q = vec2f(dot(p, vec2f(2127.1, 81.17)), dot(p, vec2f(1269.5, 283.37)));
  return fract(sin(q) * 43758.5453);
}

fn noise2(p: vec2f) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  let n = mix(
    mix(
      dot(-1.0 + 2.0 * hash2(i + vec2f(0.0, 0.0)), f - vec2f(0.0, 0.0)),
      dot(-1.0 + 2.0 * hash2(i + vec2f(1.0, 0.0)), f - vec2f(1.0, 0.0)),
      u.x
    ),
    mix(
      dot(-1.0 + 2.0 * hash2(i + vec2f(0.0, 1.0)), f - vec2f(0.0, 1.0)),
      dot(-1.0 + 2.0 * hash2(i + vec2f(1.0, 1.0)), f - vec2f(1.0, 1.0)),
      u.x
    ),
    u.y
  );
  return 0.5 + 0.5 * n;
}

fn hash1(point: vec2f) -> f32 {
  return fract(sin(dot(point, vec2f(127.1, 311.7))) * 43758.5453123);
}

fn noise1(point: vec2f) -> f32 {
  let cell = floor(point);
  let local = fract(point);
  let blend = local * local * (3.0 - 2.0 * local);
  return mix(
    mix(hash1(cell), hash1(cell + vec2f(1.0, 0.0)), blend.x),
    mix(hash1(cell + vec2f(0.0, 1.0)), hash1(cell + vec2f(1.0, 1.0)), blend.x),
    blend.y
  );
}

fn fbm(point: vec2f) -> f32 {
  var position = point;
  var value = 0.0;
  var amplitude = 0.6;
  for (var octave = 0; octave < 3; octave += 1) {
    value += amplitude * noise1(position);
    position *= 2.0;
    amplitude *= 0.5;
  }
  return value;
}

@fragment
fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
  let t = params.time * params.timeSpeed;
  let ratio = params.resolution.x / max(params.resolution.y, 1.0);

  // --- 1. Silk Mesh Gradient Layer ---
  var tuv = uv - 0.5 + params.center;
  tuv = tuv / max(params.look.w, 0.001);

  let degree = noise2(vec2f(t * 0.1, tuv.x * tuv.y) * params.grain.w);
  tuv.y *= 1.0 / ratio;
  tuv = rot(radians((degree - 0.5) * params.blend.w + 180.0)) * tuv;
  tuv.y *= ratio;

  let frequency = params.warp.y;
  let amplitude = params.warp.w / max(params.warp.x, 0.001);
  let warpTime = t * params.warp.z;
  tuv.x += sin(tuv.y * frequency + warpTime) / amplitude;
  tuv.y += sin(tuv.x * (frequency * 1.5) + warpTime) / (amplitude * 0.5);

  let b = params.blend.z;
  let s = max(params.blend.y, 0.0);
  let blendX = (rot(radians(params.blend.x)) * tuv).x;
  let edge0 = -0.3 - b - s;
  let edge1 = 0.2 - b + s;
  let v0 = 0.5 - b + s;
  let v1 = -0.3 - b - s;
  let wx = smoothstep(edge0, edge1, blendX);
  let wy = smoothstep(v0, v1, tuv.y);

  let gradLayer1 = mix(params.color3.xyz, params.color2.xyz, wx);
  let gradLayer2 = mix(params.color2.xyz, params.color1.xyz, wx);
  let gradColor = mix(gradLayer1, gradLayer2, wy);

  // Alpha follows the exact same mix weights as the color itself, so a color set to 0 opacity
  // genuinely lets the page behind the canvas show through in the region it would have covered.
  let gradAlpha1 = mix(params.color3.w, params.color2.w, wx);
  let gradAlpha2 = mix(params.color2.w, params.color1.w, wx);
  let gradAlpha = mix(gradAlpha1, gradAlpha2, wy);

  // --- 2. Heat Flare Licks Layer ---
  let y = mix(1.0 - uv.y, uv.y, params.fromTop);
  let heatMotion = t * 0.75;
  let hx = uv.x + 0.05 * sin(y * 3.2 + heatMotion * 0.6);
  let a = fbm(vec2f(hx * 2.6, y * 1.6 - heatMotion));
  let fb = fbm(vec2f(hx * 5.3 + 4.2, y * 2.9 - heatMotion * 1.5));
  let field = a * 0.72 + fb * 0.34;
  let energy = clamp(field * 2.4 - y * 2.3, 0.0, 1.0);
  let heatMask = 0.3 * smoothstep(0.06, 0.5, energy) + 0.7 * smoothstep(0.5, 0.96, energy);
  let heatColor = mix(params.heatBaseColor.xyz, params.hotColor.xyz, energy);
  let heatAlpha = heatMask * params.heatOpacity * mix(params.heatBaseColor.w, params.hotColor.w, energy);

  // --- 3. Composite heat flare OVER the silk gradient (standard unpremultiplied "over" op) ---
  let outAlpha = heatAlpha + gradAlpha * (1.0 - heatAlpha);
  var col = vec3f(0.0);
  if (outAlpha > 0.0001) {
    col = (heatColor * heatAlpha + gradColor * gradAlpha * (1.0 - heatAlpha)) / outAlpha;
  }

  // --- 4. Film Grain & Look Grading ---
  var grainUv = uv * max(params.grain.y, 0.001);
  if (params.grain.z > 0.5) {
    grainUv += vec2f(params.time * 0.05);
  }
  let grainVal = fract(sin(dot(grainUv, vec2f(12.9898, 78.233))) * 43758.5453);
  col += (grainVal - 0.5) * params.grain.x;
  col = (col - 0.5) * params.look.x + 0.5;
  let luma = dot(col, vec3f(0.2126, 0.7152, 0.0722));
  col = mix(vec3f(luma), col, params.look.z);
  col = pow(max(col, vec3f(0.0)), vec3f(1.0 / max(params.look.y, 0.001)));
  col = clamp(col, vec3f(0.0), vec3f(1.0));

  // Premultiplied output — the canvas surface is configured for alphaMode 'premultiplied'.
  return vec4f(col * outAlpha, outAlpha);
}
`
